"""Package file with the generated `knx:` configuration."""

from __future__ import annotations

from pathlib import Path
from typing import Any

import yaml

from .const import DOMAIN
from .mapping.manifest import DOMAINS, unique_id_for

HEADER = f"""\
# Automatisch erzeugt von {DOMAIN} – nicht von Hand bearbeiten.
# Generated by {DOMAIN} – do not edit, changes are overwritten on the next import.
# Projekt / project: {{project}}
"""


def render(knx: dict[str, list[dict[str, Any]]], project: str | None) -> str:
    body = yaml.safe_dump(
        {"knx": knx} if knx else {"knx": {}},
        allow_unicode=True,
        sort_keys=False,
        default_flow_style=False,
        width=1000,
    )
    return HEADER.format(project=project or "-") + body


def write(path: Path, content: str) -> None:
    """Write atomically (runs in the executor)."""
    from homeassistant.util.file import write_utf8_file_atomic

    path.parent.mkdir(parents=True, exist_ok=True)
    write_utf8_file_atomic(str(path), content)


def read_unique_ids(path: Path) -> set[tuple[str, str]]:
    """unique_ids defined by the package file (runs in the executor)."""
    if not path.exists():
        return set()
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    return unique_ids_of_knx_config(data.get("knx") or {})


def _first(value: Any) -> Any:
    """Raw YAML allows a single address or a list (first = sending address)."""
    if isinstance(value, list):
        return value[0] if value else None
    return value


def unique_ids_of_knx_config(knx: dict[str, Any]) -> set[tuple[str, str]]:
    """(domain, unique_id) of all entities in a raw (not validated) `knx:` config."""
    out: set[tuple[str, str]] = set()
    for domain in DOMAINS:
        items = knx.get(domain) or []
        if isinstance(items, dict):
            items = [items]
        for item in items:
            if not isinstance(item, dict):
                continue
            config = {k: _first(v) if k.endswith("address") or k.startswith("address_") else v for k, v in item.items()}
            try:
                out.add((domain, unique_id_for(domain, config)))
            except (TypeError, ValueError):
                continue
    return out
